// TestCall_MixedIntFloat proves the mixed int/float argument ABI — the case
// purego.SyscallN cannot express — through the portable Call entry point.
func TestCall_MixedIntFloat(t *testing.T) {
	fn := buildSym(t, srcImix4f, "imix4f")
	var args [ffi.MaxArgs]uintptr
	args[0], args[1], args[2], args[3] = 1, 2, 3, 4
	args[4] = uintptr(math.Float32bits(0.5))
	// imix4f(1,2,3,4,0.5) = 1 + 20 + 300 + 4000 + 5000 = 9321
	r1, _, _ := ffi.Call(fn, 5, &args, 1<<4)
	if int64(r1) != 9321 {
		t.Fatalf("ffi.Call imix4f = %d, want 9321 (mixed int/float ABI wrong)", int64(r1))
	}
}

